mapper.select:
SELECT
    CASE
        WHEN EXISTS (
            SELECT 1
            FROM place_visit_history
            WHERE user_email = #{userEmail}
              AND place_id = #{placeId}
        )
        OR EXISTS (
            SELECT 1
            FROM place_review
            WHERE user_email = #{userEmail}
              AND place_id = #{placeId}
        )
        THEN TRUE
        ELSE FALSE
    END AS visited
